### task-68c2bd28.py
def transform(grid):
    """Decode the repeated marker lattice to the compact color matrix."""
    h, w = len(grid), len(grid[0])
    # Marker positions are at regular row/column intervals; 9 marks empty slots.
    rows = range(7, h, 3)
    cols = range(3, w, 4)
    lattice = [[1 if grid[r][c] == 9 else grid[r][c] for c in cols] for r in rows]
    # A cell gets the color shared by its four corner markers; otherwise background 1.
    return [
        [lattice[i][j]
         if lattice[i][j] == lattice[i + 1][j] == lattice[i][j + 1] == lattice[i + 1][j + 1]
         else 1
         for j in range(len(lattice[0]) - 1)]
        for i in range(len(lattice) - 1)
    ]


### task-cc637199.py
def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Extend each 2 seed rightward; the marker becomes 4.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                out[r][c] = 4
                for x in range(c + 1, w):
                    if grid[r][x] == 5:
                        out[r][x] = 2
    # Corner 9 blocks extend toward each other in vertical 2-wide stripes.
    for r in range(h):
        if grid[r][-2:] == [9, 9]:
            for y in range(r + 1, h):
                for c in (w - 2, w - 1):
                    if grid[y][c] == 5: out[y][c] = 9
        if grid[r][:2] == [9, 9]:
            for y in range(r - 1, -1, -1):
                for c in (0, 1):
                    if grid[y][c] == 5: out[y][c] = 9
    return out


