from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    color = min(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in cells), min(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out


### task-e617133d.py
def transform(grid):
    # Fill enclosed regions of the background color with 4.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            edge = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == bg and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if not edge:
                for y, x in comp:
                    out[y][x] = 4
    return out


### task-48b289ca.py
def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda k: sum(v == k for row in grid for v in row))
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = []
            while todo:
                y, x = todo.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (dy or dx) and 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            todo.append((yy, xx))
            if len(cells) >= 4:
                top = min(y for y, x in cells)
                bottom = max(y for y, x in cells)
                left = min(x for y, x in cells)
                right = max(x for y, x in cells)
                boxes.append((top, bottom, left, right, color))
    out = [[bg] * w for _ in range(h)]
    for top, bottom, left, right, color in boxes:
        for y in range(top, bottom + 1):
            for x in range(left, right + 1):
                out[y][x] = color
    return out


### task-d0f4c17f.py
def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                marks[r + c] = value
    period = next(p for p in range(1, h + w + 1) if all(
        s % p != t % p or a == b
        for s, a in marks.items() for t, b in marks.items()))
    palette = {s % period: value for s, value in marks.items()}
    for x in range(period):
        if x not in palette:
            near = min(palette, key=lambda q: (min((x-q) % period, (q-x) % period), q))
            palette[x] = palette[near]
    out = [[palette[(r + c) % period] for c in range(w)] for r in range(h)]
    assert len(out) == h and all(len(row) == w for row in out)
    assert all(0 <= value <= 9 for row in out for value in row)
    return out


### task-1d29db2c.py
def transform(grid):
    # Join collinear 5 markers with color 3.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    for i, (r, c) in enumerate(pts):
        for y, x in pts[i + 1:]:
            if r == y:
                for xx in range(min(c, x) + 1, max(c, x)):
                    if grid[r][xx] == bg:
                        out[r][xx] = 3
            elif c == x:
                for yy in range(min(r, y) + 1, max(r, y)):
                    if grid[yy][c] == bg:
                        out[yy][c] = 3
    return out

